<html lang="en">
<head>
<meta charset="UTF-8">
<title>AI in Clinical Decision-Making – Lancet Symposium Poster</title>
<script src="/app/vendor/infographic.min.js"></script>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body {
    width: 100%;
    height: 100%;
    background: #f8f9fa;
    font-family: 'Helvetica Neue', Arial, sans-serif;
  }
  #container {
    width: 100%;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #infographic-wrap {
    width: 100%;
    height: 100%;
  }
  #export-btn {
    position: fixed;
    top: 16px;
    right: 16px;
    padding: 8px 16px;
    background: #1e3a5f;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 13px;
    z-index: 1000;
  }
  #export-btn:hover { background: #2c5282; }
</style>
</head>
<body>
<button id="export-btn">Export SVG</button>
<div id="container"></div>
<script>
const infographic = new AntVInfographic.Infographic({
  container: '#container',
  width: '100%',
  height: '100%',
});

const syntax = `infographic hierarchy-structure
data
  title Artificial Intelligence in Clinical Decision-Making
  root
    label AI in Clinical Decision-Making
    children
      - label BACKGROUND
        children
          - label Digital health frontier with rapid AI evolution
          - label 400+ studies reviewed in Lancet Digital Health (2023)
          - label Focus: diagnostic, prognostic, and therapeutic CDSS
      - label DIAGNOSTIC PERFORMANCE
        children
          - label SENSITIVITY COMPARISON
            children
              - label AI Median Sensitivity
                value 87.5
                icon chart bar
              - label Clinician Median Sensitivity
                value 78.2
                icon user
              - label Reduction in Turnaround Time
                value 32
                icon clock
          - label BY DOMAIN (AI Sensitivity)
            children
              - label Radiology
                value 89.3
              - label Ophthalmology
                value 90.1
              - label Dermatology
                value 86.7
              - label Pathology
                value 84.0
      - label SAFETY & EQUITY
        children
          - label Bias Assessment Rate
            value 18
            icon alert triangle
          - label Performance Gap for Underrepresented Groups
            children
              - label 5–12 pp sensitivity disparity documented
              - label Dermatologyaffected by training data bias
      - label IMPLEMENTATION GAP
        children
          - label Prospective Validation Rate
            value 5
            icon x circle
          - label FDA-Cleared AI/ML Devices (2023)
            value 692
          - label Key Barriers
            children
              - label Data infrastructure & EHR fragmentation
              - label Regulatory uncertainty
              - label Clinician trust & explainability
              - label Workflow integration
      - label RECOMMENDATIONS
        children
          - label Mandate prospective validation with diverse populations
          - label Standardise bias auditing as publication requirement
          - label Develop shared safety-reporting registries
          - label Invest in FHIR/OMOP interoperability
          - label Prioritise explainability research
theme
  palette #1e3a5f #2c6e8c #14b8a6 #f59e0b #e11d48 #f8f9fa #ffffff
  base
    backgroundColor "#f8f9fa"
    titleFontFamily "Helvetica Neue, Arial, sans-serif"
    titleFontSize 28
    titleFontWeight 700
    subtitleFontFamily "Helvetica Neue, Arial, sans-serif"
    subtitleFontSize 16
    subtitleFontWeight 400
    textFontFamily "Helvetica Neue, Arial, sans-serif"
    textFontSize 13
    textFontWeight 400
    tagFontFamily "Helvetica Neue, Arial, sans-serif"
    tagFontSize 11
    tagFontWeight 600
  stylize
    - type round-corner
      radius 8
`;

infographic.render(syntax);

document.fonts?.ready.then(() => {
  infographic.render(syntax);
}).catch((e) => console.error('Font error:', e));

document.getElementById('export-btn').addEventListener('click', async () => {
  const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
  const a = document.createElement('a');
  a.href = svgDataUrl;
  a.download = 'ai-clinical-poster.svg';
  a.click();
});
</script>
</body>
</html>
