import os
from playwright.sync_api import sync_playwright

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"

os.makedirs("/app/output", exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(
        args=[
            '--no-sandbox',
            '--disable-setuid-sandbox',
            '--disable-dev-shm-usage',
            '--disable-gpu'
        ]
    )
    page = browser.new_page(viewport={"width": 1684, "height": 2384})  # A0 portrait at 150dpi
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(3000)  # Wait for fonts and infographic to fully render

    # Export SVG first
    svg_data = page.evaluate("""async () => {
        const svgEl = document.querySelector('svg');
        if (svgEl) {
            const serializer = new XMLSerializer();
            return serializer.serializeToString(svgEl);
        }
        // Try to get from infographic
        const container = document.querySelector('#container');
        if (container && container.innerHTML) {
            const svgs = container.querySelectorAll('svg');
            if (svgs.length > 0) {
                const serializer = new XMLSerializer();
                return serializer.serializeToString(svgs[0]);
            }
        }
        return null;
    }""")

    if svg_data:
        with open("/app/output/poster.svg", "w") as f:
            f.write(svg_data)
        print("SVG exported to /app/output/poster.svg")

    # Take PNG screenshot of entire page
    page.screenshot(path=output_png, full_page=True)
    print(f"PNG saved to {output_png}")

    browser.close()

