import os
from playwright.sync_api import sync_playwright

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox',
        '--disable-setuid-sandbox',
        '--disable-dev-shm-usage',
        '--disable-gpu'
    ])
    # A0 portrait: 2384 x 3370 at 150dpi, or use viewport that captures full render
    page = browser.new_page(viewport={"width": 1200, "height": 1600})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(4000)

    # Get the rendered SVG dimensions to understand aspect ratio
    svg_info = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (svg) {
            const vb = svg.getAttribute('viewBox');
            const w = svg.getAttribute('width');
            const h = svg.getAttribute('height');
            return { viewBox: vb, width: w, height: h, bbox: svg.getBBox() };
        }
        return null;
    }""")
    print("SVG info:", svg_info)

    # Capture the #container element specifically
    container_box = page.evaluate("""() => {
        const el = document.getElementById('container');
        if (el) {
            const rect = el.getBoundingClientRect();
            return { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
        }
        return null;
    }""")
    print("Container box:", container_box)

    # Screenshot the whole page
    page.screenshot(path=output_png, full_page=True)
    print(f"PNG saved to {output_png}")

    # Also try exporting via infographic API
    svg_data = page.evaluate("""async () => {
        // Find the infographic instance
        const containers = document.querySelectorAll('[id=container], .infographic-container');
        for (const c of containers) {
            const svgs = c.querySelectorAll('svg');
            if (svgs.length > 0) {
                const serializer = new XMLSerializer();
                return serializer.serializeToString(svgs[0]);
            }
        }
        // Fallback: get any svg
        const svgs = document.querySelectorAll('svg');
        if (svgs.length > 0) {
            const serializer = new XMLSerializer();
            return serializer.serializeToString(svgs[0]);
        }
        return null;
    }""")
    if svg_data:
        with open("/app/output/poster.svg", "w") as f:
            f.write(svg_data)
        print(f"SVG also saved ({len(svg_data)} bytes)")

    browser.close()

