import os
from PIL import Image
from playwright.sync_api import sync_playwright

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox', '--disable-setuid-sandbox',
        '--disable-dev-shm-usage', '--disable-gpu',
        '--force-device-scale-factor=2'
    ])
    # A0 portrait at 150dpi: 3370 x 2384 px
    page = browser.new_page(viewport={"width": 1685, "height": 1191})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # The infographic SVG renders inside #container
    # Let's get actual pixel dimensions of what's rendered
    info = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (!svg) return null;
        const vb = svg.viewBox.baseVal;
        const bbox = svg.getBoundingClientRect();
        return {
            viewBoxW: vb.width, viewBoxH: vb.height,
            rectW: bbox.width, rectH: bbox.height,
            containerW: document.getElementById('container').offsetWidth,
            containerH: document.getElementById('container').offsetHeight
        };
    }""")
    print("Render info:", info)

    # Capture full page at 2x resolution for quality
    page.screenshot(path="/app/output/poster_preview.png", full_page=True, scale='css')
    print("Preview saved")

    # Get infographic's internal SVG (the actual rendered graphic)
    svg_str = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (svg) {
            const clone = svg.cloneNode(true);
            // Fix viewBox to match rendered size
            clone.setAttribute('width', '3370');
            clone.setAttribute('height', '2384');
            clone.setAttribute('viewBox', '0 0 3370 2384');
            const serializer = new XMLSerializer();
            return serializer.serializeToString(clone);
        }
        return null;
    }""")

    if svg_str:
        with open("/app/output/poster_internal.svg", "w") as f:
            f.write(svg_str)
        print(f"Internal SVG saved ({len(svg_str)} bytes)")

    browser.close()

# Now upscale the preview PNG to A0 at 150dpi using PIL
try:
    preview = Image.open("/app/output/poster_preview.png")
    print(f"Preview size: {preview.size}")

    # A0 at 150dpi = 3370 x 2384 pixels
    target_w, target_h = 3370, 2384
    # Scale to fit A0 aspect ratio while maintaining content
    current_w, current_h = preview.size
    aspect = current_w / current_h
    target_aspect = target_w / target_h

    if aspect > target_aspect:
        # Content is wider than A0 - scale by height
        new_h = target_h
        new_w = int(target_h * aspect)
    else:
        # Content is taller - scale by width
        new_w = target_w
        new_h = int(target_w / aspect)

    upscaled = preview.resize((new_w, new_h), Image.LANCZOS)
    upscaled.save(output_png, 'PNG', dpi=(150, 150))
    print(f"A0 poster saved to {output_png} ({new_w}x{new_h})")
except Exception as e:
    print(f"Upscale error: {e}")

