import os
import subprocess
from PIL import Image
from playwright.sync_api import sync_playwright

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

# A0 dimensions at 150dpi
A0_W = 3370
A0_H = 2384

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox', '--disable-setuid-sandbox',
        '--disable-dev-shm-usage', '--disable-gpu'
    ])
    page = browser.new_page(viewport={"width": 1200, "height": 1400})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # Get actual SVG viewBox dimensions
    svg_info = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (!svg) return null;
        const vb = svg.viewBox.baseVal;
        return { vb_w: vb.width, vb_h: vb.height };
    }""")
    print("SVG viewBox:", svg_info)

    # Render the SVG directly to a high-resolution PNG using cairosvg
    svg_str = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (svg) {
            const clone = svg.cloneNode(true);
            // Set explicit dimensions for A0 portrait
            clone.setAttribute('width', String(''' + str(A0_W) + '''));
            clone.setAttribute('height', String(''' + str(A0_H) + '''));
            clone.style.backgroundColor = '#0d2137';
            const serializer = new XMLSerializer();
            return serializer.serializeToString(clone);
        }
        return null;
    }""")

    if svg_str:
        with open("/app/output/poster_a0.svg", "w") as f:
            f.write(svg_str)
        print(f"A0 SVG saved ({len(svg_str)} bytes)")

        # Convert SVG to PNG using cairosvg
        try:
            import cairosvg
            cairosvg.svg2png(
                bytestring=svg_str.encode('utf-8'),
                write_to=output_png,
                output_width=A0_W,
                output_height=A0_H,
                bgcolor='#0d2137'
            )
            print(f"A0 PNG saved directly via cairosvg: {output_png}")
        except ImportError:
            print("cairosvg not available, using PIL fallback")
            # Fallback: render at large viewport and upscale
            page.set_viewport_size({"width": A0_W, "height": A0_H})
            page.wait_for_timeout(2000)
            page.screenshot(path=output_png, full_page=False, type='png')
            print(f"Screenshot saved at viewport size")

    browser.close()

# If cairosvg failed or wasn't available, upscale the preview
if not os.path.exists(output_png) or os.path.getsize(output_png) < 1000:
    print("Using PIL upscale approach...")
    with sync_playwright() as p:
        browser = p.chromium.launch(args=['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--disable-gpu'])
        page = browser.new_page(viewport={"width": 1685, "height": 1191})
        page.goto(html_path, wait_until='networkidle')
        page.wait_for_timeout(5000)
        page.screenshot(path="/app/output/poster_preview.png", full_page=False)
        browser.close()

    preview = Image.open("/app/output/poster_preview.png")
    # Scale to A0 while maintaining aspect ratio
    vb_aspect = 568 / 797  # From list-column-vertical output
    target_aspect = A0_W / A0_H

    if vb_aspect > target_aspect:
        new_h = A0_H
        new_w = int(A0_H * vb_aspect)
    else:
        new_w = A0_W
        new_h = int(A0_W / vb_aspect)

    upscaled = preview.resize((new_w, new_h), Image.LANCZOS)
    upscaled.save(output_png, 'PNG')
    print(f"Upscaled to {new_w}x{new_h} and saved")

