from playwright.sync_api import sync_playwright
from PIL import Image
import os

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

A0_W, A0_H = 3370, 2384

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox', '--disable-setuid-sandbox',
        '--disable-dev-shm-usage', '--disable-gpu'
    ])
    page = browser.new_page(viewport={'width': A0_W, 'height': A0_H})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # Inject script to modify the SVG viewBox to match viewport dimensions
    page.evaluate("""() => {
        const svg = document.querySelector('svg');
        if (svg) {
            // Change viewBox to match viewport, effectively scaling content to fill
            svg.setAttribute('viewBox', `0 0 ${window.innerWidth} ${window.innerHeight}`);
            // Force re-render by cloning and replacing
            const clone = svg.cloneNode(true);
            svg.parentNode.replaceChild(clone, svg);
        }
    }""")
    page.wait_for_timeout(1000)

    # Now take screenshot
    page.screenshot(path=output_png, full_page=False, type='png')

    svg_info = page.evaluate("""() => {
        const svg = document.querySelector('svg');
        const vb = svg.viewBox.baseVal;
        return { vb_w: Math.round(vb.width), vb_h: Math.round(vb.height) };
    }""")
    print('SVG viewBox after modification:', svg_info)

    browser.close()

# Verify
img = Image.open(output_png)
print(f'Final: {img.size}')
w, h = img.size
navy = (13, 33, 55)
different = sum(1 for y in range(0, h, 5) for x in range(0, w, 5)
               if max(abs(img.getpixel((x,y))[i]-navy[i]) for i in range(3)) > 20)
total = (w//5)*(h//5)
print(f'Non-navy: {different}/{total} = {100*different/total:.1f}%')

