from playwright.sync_api import sync_playwright
from PIL import Image
import os, base64, io

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

A0_W, A0_H = 3370, 2384

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox', '--disable-setuid-sandbox',
        '--disable-dev-shm-usage', '--disable-gpu'
    ])
    page = browser.new_page(viewport={'width': A0_W, 'height': A0_H})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # Try to get the infographic's internal canvas/SVG at higher resolution
    # by modifying the SVG viewBox to match the page viewport
    result = page.evaluate("""async () => {
        const svg = document.querySelector('svg');
        if (!svg) return { error: 'no svg' };

        // Try to get the original unscaled SVG dimensions
        const vb = svg.viewBox.baseVal;
        const origW = vb.width;
        const origH = vb.height;

        // Create a higher-res version by setting viewBox to match viewport
        const newVB = `0 0 ${window.innerWidth} ${window.innerHeight}`;
        svg.setAttribute('viewBox', newVB);

        // Force browser to re-render at new viewBox
        svg.setAttribute('width', String(window.innerWidth));
        svg.setAttribute('height', String(window.innerHeight));

        // Wait a bit for reflow
        await new Promise(r => setTimeout(r, 500));

        // Get the serialized SVG
        const serializer = new XMLSerializer();
        const svgStr = serializer.serializeToString(svg);

        return {
            origW, origH,
            newVB,
            svgLength: svgStr.length,
            viewport: { w: window.innerWidth, h: window.innerHeight }
        };
    }""")
    print('Result:', result)

    # Take screenshot after the modification
    page.screenshot(path='/app/output/modified.png', full_page=False, type='png')

    # Also try exporting the infographic to PNG via its own API
    export_result = page.evaluate("""async () => {
        try {
            // Get infographic instance
            const container = document.getElementById('container');
            const charts = container.querySelectorAll('canvas');
            if (charts.length > 0) {
                return { hasCanvas: charts.length, canvasSizes: Array.from(charts).map(c => ({w: c.width, h: c.height})) };
            }
            return { hasCanvas: 0 };
        } catch(e) {
            return { error: e.message };
        }
    }""")
    print('Export result:', export_result)

    browser.close()

# Check the modified screenshot
img = Image.open('/app/output/modified.png')
print(f'Modified size: {img.size}')
w, h = img.size
navy = (13, 33, 55)
different = sum(1 for y in range(0, h, 5) for x in range(0, w, 5)
               if max(abs(img.getpixel((x,y))[i]-navy[i]) for i in range(3)) > 20)
total = (w//5)*(h//5)
print(f'Non-navy: {different}/{total} = {100*different/total:.1f}%')

