from playwright.sync_api import sync_playwright
import cairosvg
import os

html_path = "file:///app/ai-poster-infographic.html"
output_png = "/app/output/final_poster.png"
os.makedirs("/app/output", exist_ok=True)

A0_W, A0_H = 3370, 2384

with sync_playwright() as p:
    browser = p.chromium.launch(args=[
        '--no-sandbox', '--disable-setuid-sandbox',
        '--disable-dev-shm-usage', '--disable-gpu'
    ])
    page = browser.new_page(viewport={'width': 1200, 'height': 1400})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # Get the SVG from browser with explicit A0 dimensions
    svg_str = page.evaluate(f"""() => {{
        const svg = document.querySelector('svg');
        if (!svg) return null;
        // Set explicit A0 dimensions
        svg.setAttribute('width', '{A0_W}');
        svg.setAttribute('height', '{A0_H}');
        // Keep the original viewBox so content scales properly
        const serializer = new XMLSerializer();
        return serializer.serializeToString(svg);
    }}""")

    browser.close()

if svg_str:
    # Render SVG to PNG at A0 resolution
    cairosvg.svg2png(
        bytestring=svg_str.encode('utf-8'),
        write_to=output_png,
        output_width=A0_W,
        output_height=A0_H,
        background_color='#0d2137'
    )

    import os
    size = os.path.getsize(output_png)
    print(f"A0 poster saved: {output_png}")
    print(f"File size: {size//1024}KB")
    print(f"Dimensions: {A0_W}x{A0_H} at 150dpi")

