from playwright.sync_api import sync_playwright
from PIL import Image
import cairosvg
import os

html_path = 'file:///app/ai-poster-infographic.html'
output_png = '/app/output/final_poster.png'
os.makedirs('/app/output', exist_ok=True)
A0_W, A0_H = 3370, 2384

with sync_playwright() as p:
    browser = p.chromium.launch(args=['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--disable-gpu'])
    page = browser.new_page(viewport={'width': 1200, 'height': 1400})
    page.goto(html_path, wait_until='networkidle')
    page.wait_for_timeout(5000)

    # Get the SVG with the original viewBox intact, but set explicit pixel dimensions
    svg_str = page.evaluate(f'''() => {{
        const svg = document.querySelector(\"svg\");
        if (!svg) return null;
        // Set A0 pixel dimensions (will scale from viewBox)
        svg.setAttribute(\"width\", \"{A0_W}\");
        svg.setAttribute(\"height\", \"{A0_H}\");
        const serializer = new XMLSerializer();
        return serializer.serializeToString(svg);
    }}''')

    vb_info = page.evaluate('''() => {
        const svg = document.querySelector(\"svg\");
        const vb = svg.viewBox.baseVal;
        return { vb_w: Math.round(vb.width), vb_h: Math.round(vb.height) };
    }''')
    print('Original viewBox:', vb_info)
    browser.close()

# Render with cairosvg at exact A0 dimensions
if svg_str:
    # Also add background color to the SVG root
    svg_str = svg_str.replace('<svg ', '<svg style=\"background:#0d2137\" ', 1)

    cairosvg.svg2png(
        bytestring=svg_str.encode('utf-8'),
        write_to=output_png,
        output_width=A0_W,
        output_height=A0_H
    )
    print(f'Cairosvg A0: {A0_W}x{A0_H} saved')

# Verify
img = Image.open(output_png)
print(f'Result: {img.size}, {os.path.getsize(output_png)//1024}KB')
w, h = img.size
